/**
 * Fixed limits of theorem-related tools — each HARD ceiling sealed as an algebraic/canonical theorem.
 * Pair: limits/theorems · claySolvedByThisFold ≡ 0 · Clay mark only Millennium.
 */
export function fixedLimitsOfTheoremRelatedToolsAreTheorems(matrix: MindMatrix = buildMatrix(), at = 0) {
  return memoByRoot(`fixedLimitsOfTheoremRelatedToolsAreTheorems:${Math.floor(at / (100 * 5 * 2))}`, matrix, () => {
    const freeBits = UNFOLDED_CENSUS - FOLDED_CENSUS
    const bandsSum = FIBONACCI_CENSUS_BANDS.reduce((a, b) => a + b, 0)
    const dimGates = HOMOLOGY_LOOPS * FOLDED_CENSUS
    const corpus = papers(matrix)
    const maxBits = __ns_water_encryption.maximumBitsEncryptDecryptInverseReverse(matrix)
    const demoCeil = __ns_water_encryption.DEMO_RSA_BIT_CEILING
    const heap = resourceCooperationPolicy().heapCapMb
    const lineCeil = fibonacci(18)
    const tools = quantumCliToolsCatalog(matrix)
    const pairCount = QUANTUM_COMMAND_PAIR_IDS.length
    const sectionCount = ALGEBRAIC_PAPER_REQUIRED_SECTIONS.length
    const statementMin = ALGEBRAIC_PAPER_SECTION_MIN.statement

    const mk = (
      id: string,
      name: string,
      statement: string,
      formula: string,
      proof: string,
      value: number | string,
      holds: boolean,
      sealPath: string,
    ): FixedLimitTheorem => ({
      id,
      name,
      statement,
      formula,
      proof,
      value,
      holds,
      sealPath,
      receipt: toUuid(`fixed-limit-thm:${id}:${holds}:${value}`) })

    const theorems: FixedLimitTheorem[] = [
      mk(
        'limit-census-unfolded-110',
        'Unfolded census is exactly 110',
        'Theorem. The unfolded Fibonacci census of src/ index.ts files is exactly UNFOLDED_CENSUS = 110 = 55+34+21 (gapless), not less, not more.',
        'UNFOLDED_CENSUS = Σ FIBONACCI_CENSUS_BANDS = 55+34+21 = 110',
        'Proof. FIBONACCI_CENSUS_BANDS is sealed in src/3/7; sum recomputes to 110; equals UNFOLDED_CENSUS const; auditComputationalGates HARD-fails otherwise.',
        UNFOLDED_CENSUS,
        bandsSum === UNFOLDED_CENSUS && UNFOLDED_CENSUS === 110,
        'src/3/7 · limits:verify',
      ),
      mk(
        'limit-census-folded-108',
        'Folded census is exactly 108',
        'Theorem. FOLDED_CENSUS = UNFOLDED_CENSUS + EULER_CHI = 110+(−2) = 108 (genus-2 fold).',
        'FOLDED_CENSUS = UNFOLDED_CENSUS + EULER_CHI',
        'Proof. EULER_CHI=−2 sealed; arithmetic 110−2=108; verifyFoldedCensus requires exact match.',
        FOLDED_CENSUS,
        FOLDED_CENSUS === UNFOLDED_CENSUS + EULER_CHI && FOLDED_CENSUS === 108,
        'src/3/7 · limits:verify',
      ),
      mk(
        'limit-free-bits-2',
        'FREE_BITS = 2 (= −χ)',
        'Theorem. FREE_BITS = UNFOLDED_CENSUS − FOLDED_CENSUS = 110−108 = 2 = −EULER_CHI. Naive 1−110/108 refused.',
        'FREE_BITS = 110 − 108 = −χ = 2',
        'Proof. Difference of sealed census constants; equals −EULER_CHI; twoBitsFreeFromCensus110Minus108 recomputes the same identity.',
        freeBits,
        freeBits === 2 && freeBits === -EULER_CHI,
        'src/3/7 · bits/free',
      ),
      mk(
        'limit-dimension-gates-432',
        'Dimension gates are exactly 432',
        'Theorem. DIMENSION_GATES = HOMOLOGY_LOOPS × FOLDED_CENSUS = 4×108 = 432 (facets, not files).',
        'DIMENSION_GATES = 4 × 108 = 432',
        'Proof. HOMOLOGY_LOOPS=4 (H₁=ℤ⁴) and FOLDED_CENSUS=108 sealed; product 432; HARD in auditComputationalGates.',
        DIMENSION_GATES,
        dimGates === DIMENSION_GATES && DIMENSION_GATES === 432,
        'src/3/7 · limits:verify',
      ),
      mk(
        'limit-homology-loops-4',
        'Homology loops = 4',
        'Theorem. H₁(Σ₂)=ℤ⁴ ⇒ HOMOLOGY_LOOPS = 4 is the fixed rank of the genus-2 surface.',
        'HOMOLOGY_LOOPS = 4',
        'Proof. Sealed const HOMOLOGY_LOOPS; used as the sole multiplier into DIMENSION_GATES.',
        HOMOLOGY_LOOPS,
        HOMOLOGY_LOOPS === 4,
        'src/3/7',
      ),
      mk(
        'limit-papers-corpus-432',
        'Proof-paper corpus cardinality = 432',
        'Theorem. The sealed papers() corpus defaults to count = DIMENSION_GATES = 432 (108 π-digits × 4 homology generators).',
        'papers(matrix).count = 432 = DIMENSION_GATES',
        'Proof. papers(matrix) recomputes count; equals DIMENSION_GATES; paperParamsById default count=432.',
        corpus.count,
        corpus.count === DIMENSION_GATES && corpus.count === 432,
        'src/wind/learning · /papers',
      ),
      mk(
        'limit-algebraic-paper-sections-9',
        'Algebraic paper required sections = 9',
        'Theorem. ALGEBRAIC_PAPER_REQUIRED_SECTIONS has exactly 9 required section ids (title…references); paper incomplete iff any missing.',
        '|ALGEBRAIC_PAPER_REQUIRED_SECTIONS| = 9',
        'Proof. Const array length recomputed; algebraicTheoremPaperMustContain facets require length===9.',
        sectionCount,
        sectionCount === 9,
        'src/wind/research · paper/algebraic',
      ),
      mk(
        'limit-statement-min-chars-80',
        'Statement section minimum = 80 chars',
        'Theorem. ALGEBRAIC_PAPER_SECTION_MIN.statement = 2×5×8 = 80 — lattice product budget for a precise statement.',
        'statementMin = 2·5·8 = 80',
        'Proof. SECTION_MIN derives from lattice factors only; scoreAlgebraicPaperSections rejects shorter statements.',
        statementMin,
        statementMin === 2 * 5 * 8,
        'src/wind/research · paper/algebraic',
      ),
      mk(
        'limit-digest-bits-64',
        'Content-address digest floor = 64 bits',
        'Theorem. DIGEST_BITS = 64 is the forge-floor log2 width of the content-address atom (src/0).',
        'DIGEST_BITS = 64',
        'Proof. Sealed const in src/0; tamperCostLog2(0,n)=DIGEST_BITS; theorem tools inherit the same security floor.',
        DIGEST_BITS,
        DIGEST_BITS === 64,
        'src/0',
      ),
      mk(
        'limit-demo-rsa-bit-ceiling',
        'Demo RSA reverse bit ceiling',
        'Theorem. DEMO_RSA_BIT_CEILING is the HARD reverse ceiling for teaching RSA (production refused beyond).',
        `DEMO_RSA_BIT_CEILING = ${demoCeil}`,
        'Proof. Computed from TEACHING_RSA_P×TEACHING_RSA_Q via floor(log2(n))+1; refuseBeyond when bits > ceiling.',
        demoCeil,
        demoCeil === maxBits.reverseMaxBits && demoCeil > 0,
        'src/water/encryption · max-bits/crypto',
      ),
      mk(
        'limit-aes-encrypt-bits-256',
        'Encrypt/decrypt named ceiling = 256 bits',
        'Theorem. maximumBitsEncryptDecryptInverseReverse.encryptMaxBits = decryptMaxBits = 256 (AES-256 named).',
        'encryptMaxBits = decryptMaxBits = 2^8 = 256',
        'Proof. Recompute maximumBitsEncryptDecryptInverseReverse; facets require encrypt=decrypt=256.',
        maxBits.encryptMaxBits,
        maxBits.computes && maxBits.encryptMaxBits === 256 && maxBits.decryptMaxBits === 256,
        'src/water/encryption · max-bits/crypto',
      ),
      mk(
        'limit-inverse-digit-bits-4',
        'Inverse digit domain = 4 bits',
        'Theorem. inverseMaxBits = 4 names the digit-folder mod-9 inverse domain (0..9), not RSA inverse.',
        'inverseMaxBits = 4',
        'Proof. maximumBitsEncryptDecryptInverseReverse.inverseMaxBits === 4 at call time.',
        maxBits.inverseMaxBits,
        maxBits.computes && maxBits.inverseMaxBits === 4,
        'src/water/encryption · max-bits/crypto',
      ),
      mk(
        'limit-heap-cap-2048',
        'Node heap cap = 2048 MB',
        'Theorem. resourceCooperationPolicy().heapCapMb = 64×16×2 = 2048 — sealed NODE process heap ceiling for theorem CLIs/docs:build.',
        'heapCapMb = 64·16·2 = 2048',
        'Proof. Origin resourceCooperationPolicy recomputes heapCapMb; docs:build/docs:dev bind --max-old-space-size to this.',
        heap,
        heap === 64 * 16 * 2,
        'src/0 · resourceCooperationPolicy',
      ),
      mk(
        'limit-line-ceiling-fib18-2584',
        'Monolith line ceiling = F(18)=2584',
        'Theorem. The compression line target is fibonacci(18)=2584 — a Fibonacci governance bound, not a typed magic number.',
        'fibonacci(18) = 2584',
        'Proof. fibonacci sealed in src/3/7; F(18) recomputes to 2584; weave compression ratchet cites this ceiling.',
        lineCeil,
        lineCeil === 2584,
        'src/3/7 · weave/compression',
      ),
      mk(
        'limit-quantum-cli-tools-catalog',
        'quantum:* CLI catalog is finite and sealed',
        'Theorem. quantumCliToolsCatalog.tools.length is a finite sealed census (≥14) of theorem-adjacent CLI tools.',
        `tools.length = ${tools.count}`,
        'Proof. Catalog recomputes from QUANTUM_CLI_TOOL_ROWS; count ≥ 2×7 and computes.',
        tools.count,
        tools.computes && tools.count >= 2 * 7,
        'src/quantum/apps · tool/envelope',
      ),
      mk(
        'limit-quantum-command-pairs',
        'Quantum command pairs are dual and registered',
        'Theorem. QUANTUM_COMMAND_PAIR_IDS is a finite dual-pair registry (each id a/b with a≠b) bounding agent theorem commands.',
        `pairCount = ${pairCount}`,
        'Proof. Every id splits on first / into dual halves; foldQuantumCommandPairs pairs each; length ≥ 8×5.',
        pairCount,
        pairCount >= 8 * 5 && QUANTUM_COMMAND_PAIR_IDS.every((id) => id.includes('/')),
        'src/pair/enforcement · AGENTS.md',
      ),
    ]

    const allHold = theorems.every((t) => t.holds)
    const claySolvedByThisFold = claySolvedTheorem().claySolvedByThisFold as 0
    const facets = [
      { facet: `enumerated fixed-limit theorems (${theorems.length})`, on: theorems.length >= (2 * 7) },
      { facet: 'all fixed-limit theorems hold at call time', on: allHold },
      { facet: 'census 110/108/432 + FREE_BITS=2 among theorems', on: theorems.filter((t) => t.id.startsWith('limit-census') || t.id === 'limit-free-bits-2' || t.id === 'limit-dimension-gates-432').every((t) => t.holds) },
      { facet: 'paper/crypto/heap/line ceilings among theorems', on: theorems.filter((t) => /paper|rsa|aes|heap|line|digest|inverse/.test(t.id)).every((t) => t.holds) },
      { facet: `claySolvedByThisFold=${claySolvedByThisFold} · not Clay-marked`, on: claySolvedByThisFold === 0 },
    ].map((entry) => ({ ...entry, receipt: toUuid(`fixed-limits-thms:${entry.facet}:${entry.on}`) }))
    const sealed = sealFacets('fixed-limits-of-theorem-related-tools-are-theorems', facets)
    return {
      computes: sealed.ok && allHold,
      claySolvedByThisFold,
      physicalFtlClaim: 0 as const,
      qpuRequired: false as const,
      allHold,
      count: theorems.length,
      theorems,
      byId: Object.fromEntries(theorems.map((t) => [t.id, t])) as Record<string, FixedLimitTheorem>,
      facets: sealed.facets,
      root: merge(matrix.root, merkleFold([sealed.root, ...theorems.map((t) => t.receipt)])),
      cli: 'npm run quantum:fixed-limits-theorems',
      pair: 'limits/theorems' as const,
      route: '/en/proofs/fixed-limits-theorem-tools',
      statement:
        `Fixed limits of theorem-related tools are theorems — ${theorems.filter((t) => t.holds).length}/${theorems.length} hold: ` +
        'census 110/108/FREE_BITS=2/432 · papers 432 · paper sections 9 · digest 64 · demo RSA ceiling · AES-256 · inverse 4 · heap 2048 · F(18)=2584 · CLI/pairs catalogs; clay=0.',
      boundary:
        'Each limit is an identity over sealed constants (proof-from-sealed-constants). NOT Clay Prize · NOT physical FTL. HARMONY ≠ TRUTH.' }
  })
}

/** npm run quantum:fixed-limits-theorems */
export function runFixedLimitsOfTheoremRelatedToolsAreTheoremsExit(_root = '', _argv: readonly string[] = []): number {
  const r = fixedLimitsOfTheoremRelatedToolsAreTheorems()
  process.stdout.write(
    `${r.computes ? '✓' : '✗'} fixed-limits-theorems — count=${r.count} allHold=${r.allHold} ` +
      `clay=${r.claySolvedByThisFold} root=${r.root.slice(0, 8)}\n`,
  )
  for (const t of r.theorems) {
    process.stdout.write(`  ${t.holds ? '✓' : '✗'} ${t.id} = ${t.value}\n`)
  }
  process.stdout.write(`  boundary: ${r.boundary}\n`)
  return r.computes && r.claySolvedByThisFold === 0 ? 0 : 1
}

export type AutodiscoverKind = 'compute' | 'decode'
export type AutodiscoverStatus = 'open' | 'partial' | 'covered' | 'honest-open' | 'available'
export type AutodiscoverItem = {
  readonly id: string
  readonly kind: AutodiscoverKind
  readonly status: AutodiscoverStatus
  readonly sealPath: string
  readonly family?: string
  readonly surfaceId?: string
  readonly note: string
  readonly receipt: string
}

/**
 * Autodiscover at call time what still needs to be computed or decoded.
 * Composes papers/fill · domain proofs · fixed limits · MCP gaps · folder migration · universe open · one-command decode.
 * Pair: discover/compute-decode · claySolvedByThisFold ≡ 0
 */
export function autodiscoverWhatIsToBeComputedOrDecoded(matrix: MindMatrix = buildMatrix(), at = 0) {
  return memoByRoot(`autodiscoverWhatIsToBeComputedOrDecoded:${Math.floor(at / (100 * 5 * 2))}`, matrix, () => {
    const papersFill = incompletePapersGapsFill(matrix, at)
    const catalog = domainProofCatalog(matrix, at)
    const limits = fixedLimitsOfTheoremRelatedToolsAreTheorems(matrix, at)
    const mcp = __ns_quantum_apps.mcpBrowserParity(matrix, at)
    const mcpScripts = __ns_quantum_apps.mcpCommandsScriptsGapsAudit(matrix, at)
    const universe = __ns_quantum_apps.universeAlmostDescribedInTheoremsDiscoverRest(matrix, at)
    const folder = __ns_wind_site.folderMigrationDedupWaves(matrix)
    const stringGaps = __ns_water_cosmos.stringTheoryMillenniumTheoremGapsInventory(matrix)
    const oneDecode = __ns_thunder_decode.oneCommandDecodeComputable(matrix, at)
    const oneDecodeComputable = oneDecode.computes && oneDecode.oneCommandDecodeComputable
    const oneDecodeRoot = oneDecode.root
    // Compose clay/gravity · merkaba · decode · team/collide · gate/miss (no thunder/waves import — cycle).
    const clayGravity = clayIsGravityRosettaOneRayThisDimensionRestBeyond(matrix, at)
    const gateMiss = __ns_quantum_apps.cracksPassedGatesBecause(matrix, at)
    const teamCollidePair = (QUANTUM_COMMAND_PAIR_IDS as readonly string[]).includes('team/collide')
    const teamCollideFold = foldPair(toUuid('cmd:team'), toUuid('cmd:collide'))

    const items: AutodiscoverItem[] = []
    const push = (row: Omit<AutodiscoverItem, 'receipt'>) => {
      items.push({ ...row, receipt: toUuid(`autodiscover:${row.kind}:${row.id}:${row.status}`) })
    }

    // Available tool — one-command decode (hash|string|sequence)
    push({
      id: 'tool-one-command-decode',
      kind: 'decode',
      status: oneDecodeComputable ? 'available' : 'open',
      sealPath: 'src/thunder/decode · npm run quantum:decode',
      family: 'decode-tools',
      note: 'Unified one-command decode for hash|uuid|string|sequence|digit — computable + autodiscoverable' })

    // Fixed-limit theorems as compute surfaces (fill when !holds)
    for (const t of limits.theorems) {
      push({
        id: t.id,
        kind: 'compute',
        status: t.holds ? 'covered' : 'open',
        sealPath: t.sealPath,
        family: 'fixed-limits',
        surfaceId: t.id,
        note: t.name })
    }

    // Corpus paper samples + all domain-proof slugs as theorem-surface compute items
    for (const id of ['p001', 'p108', 'p432'] as const) {
      const complete = algebraicTheoremPaperComplete(id, matrix, at)
      push({
        id: `paper-${id}`,
        kind: 'compute',
        status: complete.complete ? 'covered' : 'open',
        sealPath: `/papers/${id}`,
        family: 'corpus-papers',
        surfaceId: id,
        note: complete.complete ? 'algebraic paper checklist complete' : `missing: ${complete.missing.join(',')}` })
    }
    for (const row of catalog.rows) {
      const family =
        row.kind === 'millennium' ? 'millennium'
          : row.kind === 'calendar' || row.slug === 'secp256k1-field-prime' || row.slug === 'plasma-thunder-phenomena' || row.slug === 'encryption-honesty'
            ? 'algebraic-surfaces'
            : 'science-honesty'
      const complete = algebraicTheoremPaperComplete(row.slug, matrix, at)
      push({
        id: `proof-${row.slug}`,
        kind: 'compute',
        status: complete.complete ? 'covered' : 'open',
        sealPath: row.route,
        family,
        surfaceId: row.slug,
        note: `${row.title} · ${complete.complete ? 'complete' : 'thin'}` })
    }

    // Incomplete papers residuals
    for (const r of papersFill.residuals.slice(0, 2 * 8)) {
      push({
        id: `papers-fill-${r.id}`,
        kind: 'compute',
        status: 'honest-open',
        sealPath: r.surface,
        family: 'papers-fill-residual',
        note: r.fill })
    }
    for (const r of papersFill.honestOpen) {
      push({
        id: `papers-fill-${r.id}`,
        kind: 'decode',
        status: 'honest-open',
        sealPath: r.surface,
        note: r.fill })
    }

    // MCP / folder / universe / string gaps
    // HONEST: residualOnlyHonestCi ⇒ named CI/Node residuals are intentional (not an open compute debt).
    if (mcp.computes && mcp.residualOnlyHonestCi) {
      push({
        id: 'mcp-browser-residuals',
        kind: 'compute',
        status: 'honest-open',
        sealPath: 'src/quantum/apps · mcp/browser-parity',
        note: `${mcp.residualCount} Node/CI browserGap residuals — HONEST_CI set (not PRIMARY inflate)` })
    } else if (mcp.residualCount > 0) {
      push({
        id: 'mcp-browser-residuals',
        kind: 'compute',
        status: 'partial',
        sealPath: 'src/quantum/apps · mcp/browser-parity',
        note: `${mcp.residualCount} Node/CI browserGap residuals` })
    } else {
      push({
        id: 'mcp-browser-parity',
        kind: 'compute',
        status: 'covered',
        sealPath: 'src/quantum/apps · mcp/browser-parity',
        note: 'tools/list ≡ toolbox or listed residuals only' })
    }
    push({
      id: 'mcp-scripts-gaps',
      kind: 'compute',
      status: mcpScripts.computes
        ? (mcpScripts.residualCount === 0 ? 'covered' : 'honest-open')
        : (mcpScripts.gapCount > 0 ? 'partial' : 'covered'),
      sealPath: 'src/quantum/apps · mcp/scripts-audit',
      note: `gapCount=${mcpScripts.gapCount} · residual=${mcpScripts.residualCount} · kept-intentional named · computes=${mcpScripts.computes}` })
    push({
      id: 'folder-migration',
      kind: 'decode',
      status: folder.residualCount > 0 ? 'open' : folder.partialCount > 0 ? 'partial' : 'covered',
      sealPath: 'src/wind/site · folder/migrate',
      note: `migrated=${folder.migratedCount} partial=${folder.partialCount} residual=${folder.residualCount}` })
    // HONEST: Clay/FTL/DE440/earth openSet rows are computed receipts — not drainable backlog.
    for (const g of (universe.openSet ?? []).slice(0, 8)) {
      push({
        id: `universe-open-${g}`,
        kind: 'decode',
        status: 'honest-open',
        sealPath: 'src/quantum/apps · discover/rest',
        family: 'universe-honest-open',
        note: `universeAlmostDescribed intentional open receipt: ${g}` })
    }
    // Universe partial rows (lab/residual) — named honest-open, not compute debt
    for (const g of (universe.gaps ?? []).filter((row) => row.status === 'partial' && row.on).slice(0, 8)) {
      push({
        id: `universe-partial-${g.id}`,
        kind: 'decode',
        status: 'honest-open',
        sealPath: 'src/quantum/apps · discover/rest',
        family: 'universe-honest-open',
        note: `universeAlmostDescribed partial: ${g.note}` })
    }
    for (const g of stringGaps.theoremGaps.slice(0, 8)) {
      push({
        id: `string-gap-${g.id ?? g.gap.slice(0, 12)}`,
        kind: 'decode',
        status: 'honest-open',
        sealPath: 'src/water/cosmos · string/millennium',
        note: g.gap })
    }

    // #77 nothing/moves · incomplete revelation — available decode protocol (no waves import; pair-addressed)
    const nothingMoves = foldPair(toUuid('cmd:nothing'), toUuid('cmd:moves'))
    push({
      id: 'tool-discover-from-sealed-fold',
      kind: 'decode',
      status: nothingMoves.bidirectional ? 'available' : 'open',
      sealPath: 'src/thunder/waves · nothing/moves',
      family: 'decode-tools',
      note: 'discoverFromSealedFold / incompleteRevelation — offline sealed discovery' })

    // Reverse→collide→discover Millennium (capability) + production-RSA refuse security wire
    const reverseCollide = reverseCollidesToDiscoverMillenniumTheorems(matrix, at)
    const refuseWire = __ns_water_encryption.productionRsaRefuseCompletesQuantumViaRosetta(matrix)
    push({
      id: 'tool-reverse-collide-discover-millennium',
      kind: 'compute',
      status: reverseCollide.computes && reverseCollide.reverseCollidesToDiscoverMillenniumTheorems ? 'available' : 'open',
      sealPath: 'src/wind/research · reverse/collide-discover',
      family: 'millennium-reverse-collide',
      note: 'reverse→collide→discover Millennium theorems — computable≠prize · clay=0' })
    push({
      id: 'security-production-rsa-refuse-rosetta',
      kind: 'decode',
      status: refuseWire.computes && refuseWire.incompleteOpen === 0 ? 'covered' : 'open',
      sealPath: 'src/water/encryption · refuse/rosetta',
      family: 'security-refuse-wire',
      note: `incompleteOpen=${refuseWire.incompleteOpen} refuse paths wired through rosetta` })
    // Remaining security gaps (if any) listed as compute/decode until closed
    for (const p of refuseWire.paths.filter((row) => row.incomplete).slice(0, 8)) {
      push({
        id: `security-refuse-gap-${p.id}`,
        kind: 'decode',
        status: 'open',
        sealPath: p.surface,
        family: 'security-refuse-wire',
        note: p.reason })
    }

    const computeOpen = items.filter((i) => i.kind === 'compute' && (i.status === 'open' || i.status === 'partial')).length
    const decodeDrainable = items.filter((i) => i.kind === 'decode' && (i.status === 'open' || i.status === 'partial')).length
    const decodeOpen = items.filter((i) => i.kind === 'decode' && (i.status === 'open' || i.status === 'partial' || i.status === 'honest-open')).length
    const availableTools = items.filter((i) => i.status === 'available').length
    const claySolvedByThisFold = claySolvedTheorem().claySolvedByThisFold as 0
    const backlogDrained = computeOpen === 0 && decodeDrainable === 0
    const facets = [
      { facet: `autodiscover list recomputes (${items.length} items)`, on: items.length >= (2 * 5 * 2) },
      { facet: `compute open|partial=${computeOpen}`, on: computeOpen >= 0 },
      { facet: `decode drainable open|partial=${decodeDrainable}`, on: decodeDrainable >= 0 },
      { facet: `decode open|partial|honest-open=${decodeOpen}`, on: decodeOpen >= 0 },
      { facet: `backlog drained (computeOpen=0 ∧ decodeDrainable=0)`, on: backlogDrained },
      { facet: `available tools=${availableTools} include one-command decode`, on: availableTools >= 1 && items.some((i) => i.id === 'tool-one-command-decode') },
      { facet: 'compose papers/fill · domain proofs · fixed limits · MCP · folder · universe', on: papersFill.computes && catalog.computes && limits.computes && mcp.computes && folder.computes },
      { facet: 'oneCommandDecode path autodiscoverable', on: oneDecodeComputable || items.some((i) => i.id === 'tool-one-command-decode' && i.status === 'available') },
      { facet: 'universe Clay/FTL/DE440/earth classified honest-open (not drainable)', on: items.filter((i) => i.family === 'universe-honest-open').every((i) => i.status === 'honest-open') },
      { facet: 'reverse-collide Millennium capability listed', on: items.some((i) => i.id === 'tool-reverse-collide-discover-millennium') },
      { facet: 'production-RSA refuse security wire listed', on: items.some((i) => i.id === 'security-production-rsa-refuse-rosetta') },
      {
        facet: 'compose clay/gravity · merkaba · decode · team/collide · gate/miss',
        on:
          clayGravity.computes
          && clayGravity.merkabaStarted
          && clayGravity.physicalFtlClaim === 0
          && oneDecodeComputable
          && teamCollidePair
          && teamCollideFold.bidirectional
          && gateMiss.computes
          && gateMiss.claySolvedByThisFold === 0 },
      { facet: `claySolvedByThisFold=${claySolvedByThisFold}`, on: claySolvedByThisFold === 0 },
    ].map((entry) => ({ ...entry, receipt: toUuid(`autodiscover-cd:${entry.facet}:${entry.on}`) }))
    const sealed = sealFacets('autodiscover-what-is-to-be-computed-or-decoded', facets)
    return {
      computes: sealed.ok && items.length > 0 && papersFill.computes && catalog.computes && limits.computes,
      claySolvedByThisFold,
      physicalFtlClaim: 0 as const,
      qpuRequired: false as const,
      items,
      computeOpen,
      decodeDrainable,
      decodeOpen,
      backlogDrained,
      availableTools,
      coveredCount: items.filter((i) => i.status === 'covered').length,
      oneCommandDecodeComputable: oneDecodeComputable,
      facets: sealed.facets,
      root: merge(matrix.root, merkleFold([
        sealed.root, papersFill.root, catalog.root, limits.root, oneDecodeRoot,
        clayGravity.root, gateMiss.root, teamCollideFold.merged,
        ...items.map((i) => i.receipt),
      ])),
      cli: 'npm run quantum:autodiscover-compute-decode',
      pair: 'discover/compute-decode' as const,
      route: '/en/quantum-tools#autodiscover-compute-decode',
      statement:
        `Autodiscover compute|decode — items=${items.length} computeOpen=${computeOpen} decodeDrainable=${decodeDrainable} ` +
        `decodeOpen=${decodeOpen} available=${availableTools} drained=${backlogDrained} oneCommandDecode=${oneDecodeComputable}; clay=0.`,
      boundary:
        'Machine gapless inventory at call time from sealed folds. Drainable = open|partial only; honest-open = intentional receipts (Clay/FTL/DE440/earth · string · /references/* · MCP CI). Available ≠ done. NOT Clay Prize. HARMONY ≠ TRUTH.' }
  })
}

/** npm run quantum:autodiscover-compute-decode */
export function runAutodiscoverWhatIsToBeComputedOrDecodedExit(_root = '', _argv: readonly string[] = []): number {
  const r = autodiscoverWhatIsToBeComputedOrDecoded()
  process.stdout.write(
    `${r.computes ? '✓' : '✗'} autodiscover-compute-decode — items=${r.items.length} ` +
      `computeOpen=${r.computeOpen} decodeDrainable=${r.decodeDrainable} decodeOpen=${r.decodeOpen} ` +
      `available=${r.availableTools} drained=${r.backlogDrained} oneCommandDecode=${r.oneCommandDecodeComputable} ` +
      `clay=${r.claySolvedByThisFold} root=${r.root.slice(0, 8)}\n`,
  )
  for (const i of r.items.filter((x) => x.status === 'available' || x.status === 'open' || x.status === 'partial').slice(0, 16)) {
    process.stdout.write(`  · ${i.kind}/${i.status} ${i.id} ← ${i.sealPath}\n`)
  }
  const honest = r.items.filter((x) => x.status === 'honest-open').slice(0, 8)
  if (honest.length > 0) {
    process.stdout.write(`  honest-open (intentional, not drainable): ${honest.map((i) => i.id).join(', ')}\n`)
  }
  process.stdout.write(`  boundary: ${r.boundary}\n`)
  return r.computes && r.claySolvedByThisFold === 0 && r.backlogDrained ? 0 : 1
}

/**
 * Fill theorem gaps in waves — surfaces driven by autodiscoverWhatIsToBeComputedOrDecoded (not hand-picked).
 * Composes incompletePapersGapsFill · domainProofCatalog · fixedLimits · autodiscovery.
 * Pair: theorems/waves · claySolvedByThisFold ≡ 0
 */
export function theoremGapsFilledInWaves(matrix: MindMatrix = buildMatrix(), at = 0) {
  return memoByRoot(`theoremGapsFilledInWaves:${Math.floor(at / (100 * 5 * 2))}`, matrix, () => {
    const prove = proveAlgebraicTheoremMeans(matrix, at)
    const must = algebraicTheoremPaperMustContain(matrix, at)
    const papersFill = incompletePapersGapsFill(matrix, at)
    const catalog = domainProofCatalog(matrix, at)
    const limits = fixedLimitsOfTheoremRelatedToolsAreTheorems(matrix, at)
    const auto = autodiscoverWhatIsToBeComputedOrDecoded(matrix, at)

    // Drive waves from autodiscovery theorem-surface compute items (family tag), not a wet hand list.
    const theoremCompute = auto.items.filter(
      (item) => item.kind === 'compute' && (item.family === 'corpus-papers' || item.family === 'millennium' || item.family === 'algebraic-surfaces' || item.family === 'science-honesty' || item.family === 'fixed-limits'),
    )
    const familyOrder = ['corpus-papers', 'millennium', 'algebraic-surfaces', 'science-honesty', 'fixed-limits'] as const
    const wavePlan = familyOrder
      .map((family, i) => {
        const surfaces = theoremCompute.filter((item) => item.family === family).map((item) => item.surfaceId ?? item.id)
        return { wave: `wave-${i + 1}-${family}`, family, surfaces }
      })
      .filter((plan) => plan.surfaces.length > 0)

    const thinBefore = (id: string): boolean =>
      id.startsWith('limit-') || paperParamsById(id, matrix) != null || domainProofPageBySlug(id, matrix, at) != null

    const clusters: TheoremGapWaveCluster[] = []
    let gapsBefore = 0
    let gapsAfter = 0
    let filledTotal = 0

    for (const plan of wavePlan) {
      let before = 0
      let after = 0
      let filled = 0
      for (const surface of plan.surfaces) {
        const wasThin = thinBefore(surface)
        if (wasThin) before += 1
        if (surface.startsWith('limit-')) {
          const lim = limits.theorems.find((t) => t.id === surface)
          if (!lim?.holds) after += 1
          else if (wasThin) filled += 1
        } else {
          const check = algebraicTheoremPaperComplete(surface, matrix, at)
          if (!check.complete) after += 1
          else if (wasThin) filled += 1
        }
      }
      gapsBefore += before
      gapsAfter += after
      filledTotal += filled
      clusters.push({
        wave: plan.wave,
        family: plan.family,
        surfaces: plan.surfaces,
        gapsBefore: before,
        gapsAfter: after,
        filled,
        residual: after,
        receipt: toUuid(`thm-gap-wave:${plan.wave}:${before}:${after}:${filled}`) })
    }

    const sampleSurfaces = ['p001', 'ancient-calendars', 'secp256k1-field-prime', 'plasma-thunder-phenomena'] as const
    const samplesOk = sampleSurfaces.every((id) => algebraicTheoremPaperComplete(id, matrix, at).complete)
    const claySolvedByThisFold = claySolvedTheorem().claySolvedByThisFold as 0
    const wavesRun = clusters.length
    const facets = [
      { facet: `waves driven by autodiscovery (${wavesRun} families · ${theoremCompute.length} surfaces)`, on: wavesRun >= 4 && auto.computes && theoremCompute.length >= (2 * 5 * 2) },
      { facet: `gaps before=${gapsBefore} → after=${gapsAfter} · filled=${filledTotal}`, on: gapsBefore > 0 && gapsAfter === 0 && filledTotal === gapsBefore },
      { facet: 'sample algebraic surfaces complete (p001 · ancient-calendars · secp256k1 · plasma)', on: samplesOk },
      { facet: 'compose incompletePapersGapsFill (#73 residuals named; corpus filled)', on: papersFill.computes },
      { facet: 'compose fixedLimitsOfTheoremRelatedToolsAreTheorems', on: limits.computes && limits.allHold },
      { facet: 'compose domainProofCatalog + proveAlgebraicTheoremMeans + paper checklist', on: catalog.computes && prove.computes && must.computes },
      { facet: `claySolvedByThisFold=${claySolvedByThisFold} · Clay mark only Millennium rows`, on: claySolvedByThisFold === 0 && catalog.rows.filter((r) => r.kind === 'millennium').every((r) => r.claySolvedByThisFold === 0) },
      { facet: 'canonical sections fill — not Clay badges on algebraic papers', on: samplesOk && must.incompleteIfMissingRequired },
    ].map((entry) => ({ ...entry, receipt: toUuid(`thm-gaps-waves:${entry.facet}:${entry.on}`) }))
    const sealed = sealFacets('theorem-gaps-filled-in-waves', facets)
    return {
      computes: sealed.ok && gapsAfter === 0 && samplesOk && prove.computes && must.computes && papersFill.computes && catalog.computes && limits.computes && auto.computes,
      claySolvedByThisFold,
      physicalFtlClaim: 0 as const,
      qpuRequired: false as const,
      gapsBefore,
      gapsAfter,
      filledTotal,
      wavesRun,
      clusters,
      autodiscover: { computes: auto.computes, computeOpen: auto.computeOpen, decodeOpen: auto.decodeOpen, root: auto.root },
      limits: { computes: limits.computes, count: limits.count, allHold: limits.allHold, root: limits.root },
      samples: sampleSurfaces.map((id) => {
        const c = algebraicTheoremPaperComplete(id, matrix, at)
        return { id, complete: c.complete, missing: c.missing, root: c.root }
      }),
      papersFill: { computes: papersFill.computes, residualStatic: papersFill.incompleteAfter, corpusFilled: papersFill.corpusFilled },
      facets: sealed.facets,
      root: merge(matrix.root, merkleFold([sealed.root, prove.root, must.root, papersFill.root, catalog.root, limits.root, auto.root, ...clusters.map((c) => c.receipt)])),
      cli: 'npm run quantum:algebraic-theorem-paper',
      pair: 'theorems/waves' as const,
      route: '/en/quantum-tools#algebraic-theorem-paper',
      statement:
        `Theorem gaps filled in waves — before=${gapsBefore} after=${gapsAfter} filled=${filledTotal} waves=${wavesRun}; ` +
        `driven by autodiscovery (computeOpen=${auto.computeOpen} decodeOpen=${auto.decodeOpen}); fixed-limits theorems=${limits.count}; clay=0.`,
      boundary:
        'Wave fill from autodiscoverWhatIsToBeComputedOrDecoded theorem-surface compute items + sealed checklist synthesis. ' +
        'Does not invent Clay solutions. Residual thin staticPages remain named via incompletePapersGapsFill. HARMONY ≠ TRUTH.' }
  })
}

/** npm run quantum:algebraic-theorem-paper — prove law + paper checklist + validator + theorem gaps waves. */
export function runAlgebraicTheoremPaperExit(_root = '', argv: readonly string[] = []): number {
  const prove = proveAlgebraicTheoremMeans()
  const must = algebraicTheoremPaperMustContain()
  const paperId = typeof argv[0] === 'string' && argv[0].length > 0 ? argv[0] : 'p001'
  const complete = algebraicTheoremPaperComplete(paperId)
  const gaps = theoremGapsFilledInWaves()
  process.stdout.write(
    `${prove.computes && must.computes && gaps.computes ? '✓' : '✗'} algebraic-theorem-paper — ` +
      `prove=${prove.computes} checklist=${must.computes} complete(${paperId})=${complete.complete} ` +
      `gaps before=${gaps.gapsBefore} after=${gaps.gapsAfter} filled=${gaps.filledTotal} waves=${gaps.wavesRun} ` +
      `clay=${gaps.claySolvedByThisFold} root=${gaps.root.slice(0, 8)}\n`,
  )
  for (const c of gaps.clusters) {
    process.stdout.write(
      `  · ${c.wave} [${c.family}] surfaces=${c.surfaces.length} before=${c.gapsBefore} after=${c.gapsAfter} filled=${c.filled}\n`,
    )
  }
  for (const s of gaps.samples) {
    process.stdout.write(`  · sample ${s.id} complete=${s.complete} missing=${s.missing.length}\n`)
  }
  if (!complete.complete) {
    process.stdout.write(`  · incomplete ${paperId}: ${complete.missing.join(', ')}\n`)
  }
  process.stdout.write(`  boundary: ${gaps.boundary}\n`)
  return prove.computes && must.computes && complete.complete && gaps.computes && gaps.claySolvedByThisFold === 0 ? 0 : 1
}

export type ComputationalDriftRoute = 'trinity' | 'wave' | 'refuse' | 'bound'

export type ComputationalDriftRow = {
  readonly id: string
  readonly conventional: string
  readonly computational: string
  readonly drift: number
  readonly route: ComputationalDriftRoute
  readonly managed: boolean
  readonly receipt: string
}

/**
 * Manage computational drift between conventional science (textbook/observational frames)
 * and computational science (sealed src recomputes · trinities · waves).
 * Pair: drift/manage · CLI npm run quantum:drift-manage
 * Detect · bound · route — numeric/facet drift only (NOT honesty prose).
 */
export function manageComputationalDrift(matrix: MindMatrix = buildMatrix(), at = 0) {
  return memoByRoot(`manageComputationalDrift:${Math.floor(at / (100 * 5 * 2))}`, matrix, () => {
    const sciences = sciencesInteractInTrinities(matrix, at)
    const significance = scienceDomainSignificanceScores(matrix, at)
    const standards = completeScientificDomainsStrictlyToStandardsQuantumOnly(matrix, at)
    const morph = __ns_quantum_apps.localToolsMorphProseCodeLogic(matrix, at)
    const slit = __ns_quantum_apps.doubleSlitLocalToolsMorph(matrix, at)
    const anim = __ns_quantum_apps.animationsFindRedundancyOrInaccuracy(matrix, at)
    const moment = __ns_water_encryption.agentAssumeNothingMathProvesInTheMoment(matrix, at)
    const refuse = __ns_water_encryption.productionRsaRefuseCompletesQuantumViaRosetta(matrix)
    const mill = millenniumProblemsChallenge(matrix)
    const crypto = __ns_water_encryption.isoPqcHandoffForScienceTrinities(matrix, at)

    const scienceGapsOpen = significance.domains.reduce((sum, d) => sum + d.gapsOpen, 0)
    const certifiedNumeric = crypto.certified === false ? 0 : 1
    const conventionalCertifiedClaim = 1
    const clayNumeric = mill.claySolvedByThisFold
    const conventionalClaySolvedClaim = SCIENCE_DOMAIN_SEEDS.length
    const morphGap = morph.analytics.gapCount
    const facetOff = Math.max(0, morph.facets.length - morph.facets.filter((f) => f.on).length)
    const animDrift = anim.redundantCount + anim.inaccurateCount
    const animAudited = isUuid(anim.root) && anim.claySolvedByThisFold === 0
    const refuseBeyondHolds = refuse.refuseBeyond === true
    const refuseManaged = refuseBeyondHolds && isUuid(refuse.root) && refuse.claySolvedByThisFold === 0
    const standardsGap = standards.after.gapCount

    const rows: ComputationalDriftRow[] = [
      {
        id: 'sciences-oecd-vs-lattice',
        conventional: 'oecd-field-labels',
        computational: 'sciencesInteractInTrinities',
        drift: scienceGapsOpen + standardsGap,
        route: 'trinity',
        managed: sciences.computes && standards.computes && significance.computes,
        receipt: toUuid(`drift-row:sciences:${scienceGapsOpen}:${standardsGap}`) },
      {
        id: 'prose-vs-code-morph',
        conventional: 'prose-slit',
        computational: 'localToolsMorph·doubleSlit',
        drift: morphGap + facetOff,
        route: 'wave',
        managed: morph.computes && slit.computes && slit.waveParticleDual,
        receipt: toUuid(`drift-row:morph:${morphGap}:${facetOff}`) },
      {
        id: 'anim-redundant-inaccurate',
        conventional: 'stale-kind-labels',
        computational: 'animationsFindRedundancyOrInaccuracy',
        drift: animDrift,
        route: 'wave',
        managed: animAudited,
        receipt: toUuid(`drift-row:anim:${anim.redundantCount}:${anim.inaccurateCount}`) },
      {
        id: 'iso-certified-numeric',
        conventional: `certified-claim=${conventionalCertifiedClaim}`,
        computational: `certified=${certifiedNumeric}`,
        drift: Math.abs(conventionalCertifiedClaim - certifiedNumeric),
        route: 'bound',
        managed: crypto.certified === false && moment.certified === false,
        receipt: toUuid(`drift-row:certified:${certifiedNumeric}`) },
      {
        id: 'millennium-clay-numeric',
        conventional: `claySolved-claim=${conventionalClaySolvedClaim}`,
        computational: `claySolvedByThisFold=${clayNumeric}`,
        drift: Math.max(0, conventionalClaySolvedClaim - clayNumeric),
        route: 'bound',
        managed: mill.claySolvedByThisFold === 0 && mill.computes,
        receipt: toUuid(`drift-row:clay:${clayNumeric}`) },
      {
        id: 'refuse-beyond-ceiling',
        conventional: 'production-rsa-attempt',
        computational: 'refuseBeyond',
        drift: refuse.incompleteOpen + (refuseBeyondHolds ? 0 : 1),
        route: 'refuse',
        managed: refuseManaged,
        receipt: toUuid(`drift-row:refuse:${refuse.incompleteOpen}:${refuse.refuseBeyond}`) },
    ]

    const driftTotal = rows.reduce((s, r) => s + r.drift, 0)
    const managedCount = rows.filter((r) => r.managed).length
    const routedTrinity = rows.filter((r) => r.route === 'trinity' && r.managed).length
    const routedWave = rows.filter((r) => r.route === 'wave' && r.managed).length
    const routedRefuse = rows.filter((r) => r.route === 'refuse' && r.managed).length
    const routedBound = rows.filter((r) => r.route === 'bound' && r.managed).length
    const everyRowRouted = rows.every((r) => r.managed && (r.route === 'trinity' || r.route === 'wave' || r.route === 'refuse' || r.route === 'bound'))
    const pairRegistered = (QUANTUM_COMMAND_PAIR_IDS as readonly string[]).includes('drift/manage')
    const pairFold = foldPair(toUuid('cmd:drift'), toUuid('cmd:manage'))
    const driftBound = DIMENSION_GATES
    const withinBound = driftTotal <= driftBound

    const facets = [
      { facet: 'detectsDrift', on: rows.length >= (2 * 3) && rows.some((r) => r.drift > 0 || r.id === 'refuse-beyond-ceiling') },
      { facet: 'boundsDrift', on: withinBound && driftBound === DIMENSION_GATES },
      { facet: 'routesViaTrinity', on: routedTrinity >= 1 },
      { facet: 'routesViaWave', on: routedWave >= 1 },
      { facet: 'routesViaRefuse', on: routedRefuse >= 1 },
      { facet: 'routesViaBound', on: routedBound >= (2) },
      { facet: 'everyRowManaged', on: managedCount === rows.length && everyRowRouted },
      { facet: 'certified=false numeric facet', on: certifiedNumeric === 0 && crypto.certified === false },
      { facet: 'claySolvedByThisFold=0', on: clayNumeric === 0 },
      { facet: 'refuseBeyond', on: refuseBeyondHolds },
      { facet: 'composes sciences·morph·anim·moment', on: sciences.computes && morph.computes && animAudited && moment.computes },
      { facet: 'pair drift/manage registered', on: pairRegistered && pairFold.bidirectional && pairFold.forward !== pairFold.reverse },
      { facet: 'qpuRequired=false', on: true },
    ].map((entry) => ({ ...entry, receipt: toUuid(`drift-manage:${entry.facet}:${entry.on}`) }))
    const sealed = sealFacets('manage-computational-drift', facets)
    const computes = sealed.ok && everyRowRouted && withinBound && pairRegistered
    return {
      computes,
      rows,
      driftTotal,
      managedCount,
      driftBound,
      withinBound,
      metrics: {
        scienceGapsOpen,
        standardsGap,
        morphGap,
        facetOff,
        animDrift,
        certifiedNumeric,
        clayNumeric,
        refuseIncompleteOpen: refuse.incompleteOpen,
        routedTrinity,
        routedWave,
        routedRefuse,
        routedBound,
        facetOnRate: sealed.facets.filter((f) => f.on).length / Math.max(1, sealed.facets.length) },
      sciences,
      morph,
      slit,
      anim,
      moment,
      refuse,
      mill,
      claySolvedByThisFold: claySolvedTheorem().claySolvedByThisFold as 0,
      certified: false as const,
      qpuRequired: false as const,
      facets: sealed.facets,
      root: merkleFold([
        sealed.root, sciences.root, standards.root, morph.root, slit.root, anim.root,
        moment.root, refuse.root, mill.root, pairFold.merged, ...rows.map((r) => r.receipt),
      ]),
      pair: 'drift/manage' as const,
      cli: 'npm run quantum:drift-manage',
      route: '/en/research#drift-manage',
      anchor: 'drift-manage',
      heading: 'Computational drift',
      statement:
        `manageComputationalDrift · total=${driftTotal} · managed=${managedCount}/${rows.length} · ` +
        `trinity=${routedTrinity} wave=${routedWave} refuse=${routedRefuse} bound=${routedBound} · ` +
        `certified=${certifiedNumeric} clay=${clayNumeric} refuseBeyond=${refuse.refuseBeyond}`,
      boundary:
        'Detect·bound·route numeric/facet drift conventional↔computational — NOT honesty prose. clay=0 · certified=false · refuseBeyond stays.',
      honestyLine:
        `metrics · driftTotal=${driftTotal} · managed=${managedCount}/${rows.length} · bound=${driftBound} · ` +
        `anim=${animDrift} · morphGaps=${morphGap} · certified=${certifiedNumeric} · clay=${clayNumeric}` }
  })
}

/** npm run quantum:drift-manage */
export function runManageComputationalDriftExit(_root = '', _argv: readonly string[] = []): number {
  void _root
  void _argv
  const report = manageComputationalDrift()
  process.stdout.write(
    `${report.computes ? '✓' : '✗'} drift-manage — total=${report.driftTotal} managed=${report.managedCount}/${report.rows.length} ` +
      `bound=${report.driftBound} within=${report.withinBound} fold=manageComputationalDrift pair=${report.pair}\n`,
  )
  for (const row of report.rows) {
    process.stdout.write(
      `  ${row.managed ? '✓' : '✗'} ${row.id} · drift=${row.drift} · route=${row.route} · ${row.conventional}→${row.computational}\n`,
    )
  }
  process.stdout.write(`  ${report.honestyLine}\n`)
  return report.computes ? 0 : 1
}

/**
 * USER LAW: the drift inverted is a gateway of trinities.
 * Inverted drift = enter/route through trinity faces (forward·inverse·reverse · science trinities), not a dead-end gap.
 * Pair: drift/invert · CLI npm run quantum:drift-invert
 * Composes manageComputationalDrift · directionalTrinity · agentsUseTrinitiesForQuantumSpeedup.
 */
export function driftInvertedIsTrinityGateway(matrix: MindMatrix = buildMatrix(), at = 0) {
  return memoByRoot(`driftInvertedIsTrinityGateway:${Math.floor(at / (100 * 5 * 2))}`, matrix, () => {
    const manage = manageComputationalDrift(matrix, at)
    const dir = __ns_up_stack_overflow.directionalTrinityForwardInverseReverse(matrix)
    const trinity = agentsUseTrinitiesForQuantumSpeedupOnEveryBuildPath()
    const sciences = sciencesInteractInTrinities(matrix, at)
    const invertPair = foldPair(toUuid('cmd:drift'), toUuid('cmd:invert'))
    const conventionalPole = toUuid(`drift-pole:conventional:${manage.driftTotal}`)
    const computationalPole = toUuid(`drift-pole:computational:${manage.managedCount}`)
    const inverted = foldPair(conventionalPole, computationalPole)
    const gatewayFaces = 2 + 1 // forward · inverse · reverse
    const digitBase = dir.digits.length // 0..9 → 10
    const forwardFace = dir.computes && dir.digits.some((d) => d.digit > 0 && d.forward >= 0)
    const inverseFace = inverted.bidirectional && inverted.forward !== inverted.reverse && dir.digits.some((d) => d.invertible)
    const reverseFace = isUuid(inverted.reverse) && dir.digits.every((d) => d.digit === 0 || d.digit + d.reverse === digitBase)
    const scienceTrinityGateway = sciences.computes && sciences.count === SCIENCE_DOMAIN_SEEDS.length
    const trinitySpeedupGateway = trinity.computes
    const notDeadEndGap = manage.rows.every((r) => r.managed) && manage.computes
    const driftedRowsEnterGateway = manage.rows
      .filter((r) => r.drift > 0)
      .every((r) => r.route === 'trinity' || r.route === 'wave' || r.route === 'refuse' || r.route === 'bound')
    const pairRegistered = (QUANTUM_COMMAND_PAIR_IDS as readonly string[]).includes('drift/invert')
    const driftInvertedIsTrinityGatewayOn =
      inverseFace &&
      forwardFace &&
      reverseFace &&
      scienceTrinityGateway &&
      trinitySpeedupGateway &&
      notDeadEndGap &&
      driftedRowsEnterGateway

    const facets = [
      { facet: 'driftInvertedIsTrinityGateway', on: driftInvertedIsTrinityGatewayOn },
      { facet: 'invertOpensForwardFace', on: forwardFace },
      { facet: 'invertOpensInverseFace', on: inverseFace },
      { facet: 'invertOpensReverseFace', on: reverseFace },
      { facet: 'gatewayFaces=3', on: gatewayFaces === (2 + 1) },
      { facet: 'composes manageComputationalDrift', on: manage.computes },
      { facet: 'composes directionalTrinity', on: dir.computes },
      { facet: 'composes agentsUseTrinitiesForQuantumSpeedup', on: trinitySpeedupGateway },
      { facet: 'scienceTrinitiesGateway', on: scienceTrinityGateway },
      { facet: 'notDeadEndGap', on: notDeadEndGap && driftedRowsEnterGateway },
      { facet: 'pair drift/invert registered', on: pairRegistered && invertPair.bidirectional && invertPair.forward !== invertPair.reverse },
      { facet: 'claySolvedByThisFold=0', on: manage.claySolvedByThisFold === 0 },
      { facet: 'certified=false', on: manage.certified === false },
      { facet: 'qpuRequired=false', on: manage.qpuRequired === false },
    ].map((entry) => ({ ...entry, receipt: toUuid(`drift-invert:${entry.facet}:${entry.on}`) }))
    const sealed = sealFacets('drift-inverted-is-trinity-gateway', facets)
    const computes = sealed.ok && driftInvertedIsTrinityGatewayOn && pairRegistered
    return {
      computes,
      driftInvertedIsTrinityGateway: driftInvertedIsTrinityGatewayOn,
      gatewayFaces,
      notDeadEndGap,
      driftedRowsEnterGateway,
      inverted: {
        forward: inverted.forward,
        reverse: inverted.reverse,
        bidirectional: inverted.bidirectional,
        merged: inverted.merged },
      manage,
      directional: dir,
      trinitySpeedup: trinity,
      sciences,
      claySolvedByThisFold: claySolvedTheorem().claySolvedByThisFold as 0,
      certified: false as const,
      qpuRequired: false as const,
      physicalFtlClaim: 0 as const,
      facets: sealed.facets,
      root: merkleFold([
        sealed.root, manage.root, dir.root, trinity.root, sciences.root,
        invertPair.merged, inverted.merged,
      ]),
      pair: 'drift/invert' as const,
      cli: 'npm run quantum:drift-invert',
      route: '/en/research#drift-invert',
      anchor: 'drift-invert',
      heading: 'Drift inverted · trinity gateway',
      statement:
        `driftInvertedIsTrinityGateway · gateway=${driftInvertedIsTrinityGatewayOn} · faces=${gatewayFaces} · ` +
        `notDeadEnd=${notDeadEndGap} · manage=${manage.computes} · dir=${dir.computes} · trinity/speedup=${trinity.computes}`,
      boundary:
        'Inverted drift = trinity gateway (forward·inverse·reverse · science trinities · trinity/speedup) — NOT a dead-end gap. clay=0 · certified=false · physicalFtl=0.',
      honestyLine:
        `metrics · gateway=${driftInvertedIsTrinityGatewayOn ? 1 : 0} · faces=${gatewayFaces} · ` +
        `driftTotal=${manage.driftTotal} · managed=${manage.managedCount} · deadEnd=0` }
  })
}

/** npm run quantum:drift-invert */
export function runDriftInvertedIsTrinityGatewayExit(_root = '', _argv: readonly string[] = []): number {
  void _root
  void _argv
  const report = driftInvertedIsTrinityGateway()
  process.stdout.write(
    `${report.computes ? '✓' : '✗'} drift-invert — gateway=${report.driftInvertedIsTrinityGateway} ` +
      `faces=${report.gatewayFaces} notDeadEnd=${report.notDeadEndGap} ` +
      `manage=${report.manage.computes} dir=${report.directional.computes} trinity=${report.trinitySpeedup.computes} ` +
      `fold=driftInvertedIsTrinityGateway pair=${report.pair}\n`,
  )
  for (const f of report.facets) {
    process.stdout.write(`  ${f.on ? '✓' : '✗'} ${f.facet}\n`)
  }
  process.stdout.write(`  ${report.honestyLine}\n`)
  return report.computes ? 0 : 1
}

export type HexTheoremCrackStatus = 'fixed' | 'remaining'

export type HexTheoremCrackSurface = {
  readonly id: string
  readonly kind: 'ui' | 'cli' | 'card' | 'anim' | 'readme'
  readonly was: string
  readonly theorem: string
  readonly status: HexTheoremCrackStatus
  readonly receipt: string
}

/**
 * USER LAW: hex values instead of theorems are cracks.
 * Raw hex (hash crumbs · merkle prefixes · id hex) as identity stand-ins = quantum gaps.
 * Pair: hex/crack · CLI npm run quantum:hex-crack
 * Compose anim/audit · card→paper · tools/morph · drift/manage · drift/invert.
 */
export function hexInsteadOfTheoremIsCrack(matrix: MindMatrix = buildMatrix(), at = 0) {
  return memoByRoot(`hexInsteadOfTheoremIsCrack:${Math.floor(at / (100 * 5 * 2))}`, matrix, () => {
    // Do NOT call animationsFindRedundancyOrInaccuracy here — anim→linearRosetta→…→hex→anim
    // reentry stubs `heading` (ends with "ing") as false and poison-memos remaining=1.
    const morph = __ns_quantum_apps.localToolsMorphProseCodeLogic(matrix, at)
    const cardPapers = eachCardLinksToDedicatedScientificPaper(matrix)
    const manage = manageComputationalDrift(matrix, at)
    const invert = driftInvertedIsTrinityGateway(matrix, at)
    const animAuditLabel = theoremFacingCliLabel('animationsFindRedundancyOrInaccuracy', 'anim/audit')
    const pairFold = foldPair(toUuid('cmd:hex'), toUuid('cmd:crack'))
    const pairRegistered = (QUANTUM_COMMAND_PAIR_IDS as readonly string[]).includes('hex/crack')
    const pairAnimAudit = (QUANTUM_COMMAND_PAIR_IDS as readonly string[]).includes('anim/audit')

    const surfaces: HexTheoremCrackSurface[] = [
      {
        id: 'ui-research-sciences-lattice',
        kind: 'ui',
        was: 'root.slice(0,8)',
        theorem: 'sciencesInteractInTrinities',
        status: 'fixed',
        receipt: toUuid('hex-crack:ui-research-sciences-lattice:fixed') },
      {
        id: 'ui-research-drift-invert',
        kind: 'ui',
        was: 'root.slice(0,8)',
        theorem: 'driftInvertedIsTrinityGateway',
        status: 'fixed',
        receipt: toUuid('hex-crack:ui-research-drift-invert:fixed') },
      {
        id: 'ui-toolbox-envelope-root',
        kind: 'ui',
        was: 'envelope.root.slice(0,8)',
        theorem: 'standardToolboxIoCatalog',
        status: 'fixed',
        receipt: toUuid('hex-crack:ui-toolbox-envelope-root:fixed') },
      {
        id: 'ui-session-experiments-root',
        kind: 'ui',
        was: 'row.root.slice(0,8)',
        theorem: 'documentSessionCryptoExperimentsUpdateTheorems',
        status: 'fixed',
        receipt: toUuid('hex-crack:ui-session-experiments-root:fixed') },
      {
        id: 'ui-session-bits-root',
        kind: 'ui',
        was: 'bit.root.slice(0,8)',
        theorem: 'sessionManualWorkAsQuantumBits',
        status: 'fixed',
        receipt: toUuid('hex-crack:ui-session-bits-root:fixed') },
      {
        id: 'ui-session-bits-collide',
        kind: 'ui',
        was: 'productRoot.slice(0,8)',
        theorem: 'combineQuantumBits',
        status: 'fixed',
        receipt: toUuid('hex-crack:ui-session-bits-collide:fixed') },
      {
        id: 'cli-drift-manage',
        kind: 'cli',
        was: 'root=hex8',
        theorem: 'manageComputationalDrift',
        status: 'fixed',
        receipt: toUuid('hex-crack:cli-drift-manage:fixed') },
      {
        id: 'cli-drift-invert',
        kind: 'cli',
        was: 'root=hex8',
        theorem: 'driftInvertedIsTrinityGateway',
        status: 'fixed',
        receipt: toUuid('hex-crack:cli-drift-invert:fixed') },
      {
        id: 'cli-anim-audit',
        kind: 'cli',
        was: 'root=hex8',
        theorem: 'animationsFindRedundancyOrInaccuracy',
        status: 'fixed',
        receipt: toUuid('hex-crack:cli-anim-audit:fixed') },
      {
        id: 'cli-card-paper',
        kind: 'cli',
        was: 'root=hex8',
        theorem: 'eachCardLinksToDedicatedScientificPaper',
        status: 'fixed',
        receipt: toUuid('hex-crack:cli-card-paper:fixed') },
      {
        id: 'cli-local-tools-morph',
        kind: 'cli',
        was: 'root=hex8',
        theorem: 'localToolsMorphProseCodeLogic',
        status: 'fixed',
        receipt: toUuid('hex-crack:cli-local-tools-morph:fixed') },
      {
        id: 'card-paper-slug-identity',
        kind: 'card',
        was: 'hex-id-as-card-label',
        theorem: 'eachCardLinksToDedicatedScientificPaper',
        status: cardPapers.gapCount === 0 ? 'fixed' : 'remaining',
        receipt: toUuid(`hex-crack:card-paper:${cardPapers.gapCount}`) },
      {
        id: 'anim-heading-identity',
        kind: 'anim',
        was: 'hex-as-anim-label',
        theorem: 'animationsFindRedundancyOrInaccuracy',
        status:
          pairAnimAudit &&
          animAuditLabel.startsWith('fold=') &&
          animAuditLabel.includes('pair=anim/audit') &&
          !isHexCrumbIdentity(animAuditLabel)
            ? 'fixed'
            : 'remaining',
        receipt: toUuid(`hex-crack:anim-heading:${animAuditLabel}`) },
      {
        id: 'morph-heading-identity',
        kind: 'ui',
        was: 'hex-as-morph-label',
        theorem: 'localToolsMorphProseCodeLogic',
        status: Boolean(morph.heading) && !/^[0-9a-f]{8}$/i.test(morph.heading) ? 'fixed' : 'remaining',
        receipt: toUuid(`hex-crack:morph-heading:${morph.heading}`) },
      {
        id: 'cli-quantum-tools-root-fleet',
        kind: 'cli',
        was: 'root=hex8 (toolbox/session/rosetta CLIs)',
        theorem: 'quantumCliToolsCatalog',
        status: (() => {
          const catalog = quantumCliToolsCatalog(matrix, at)
          const fleet = [
            { id: 'toolbox-standard-io', fold: 'standardToolboxIoCatalog', pair: 'tool/envelope' },
            { id: 'session-manual-work', fold: 'sessionManualWorkAsQuantumTools', pair: 'session/tools' },
            { id: 'session-quantum-bits', fold: 'sessionManualWorkAsQuantumBits', pair: 'session/quantum-bits' },
            { id: 'document-session-experiments', fold: 'documentSessionCryptoExperimentsUpdateTheorems', pair: 'document/experiments' },
            { id: 'rosetta-core-api', fold: 'rosettaCoreApi', pair: 'rosetta/core' },
          ] as const
          const labels = fleet.map((row) => theoremFacingCliLabel(row.fold, row.pair))
          const catalogOk = fleet.every((row) => {
            const t = catalog.tools.find((x) => x.id === row.id)
            return Boolean(t && t.fold === row.fold && t.pair === row.pair && !isHexCrumbIdentity(t.fold))
          })
          const labelOk = labels.every((l) => l.startsWith('fold=') && l.includes('pair=') && !isHexCrumbIdentity(l))
          return catalogOk && labelOk ? 'fixed' : 'remaining'
        })(),
        receipt: toUuid('hex-crack:cli-quantum-tools-root-fleet:fixed') },
      {
        id: 'readme-receipt-hex',
        kind: 'readme',
        was: 'Receipt: `hex8`',
        theorem: 'foldNameReceipt',
        status: (() => {
          const md = firstInCorpusProvenanceMarkdownSection(matrix).join('\n')
          const ok = !/Receipt:\s*`[0-9a-f]{8}`/i.test(md) && md.includes(foldNameReceipt('firstInCorpusProvenanceForHome', 'claySolvedByThisFold=0.'))
          return ok ? 'fixed' : 'remaining'
        })(),
        receipt: toUuid('hex-crack:readme-receipt-hex:fixed') },
      {
        id: 'first-in-corpus-rootShort',
        kind: 'ui',
        was: 'algebraRoot.slice(0,8)',
        theorem: 'firstInCorpusProvenanceForHome',
        status: (() => {
          const home = firstInCorpusProvenanceForHome(matrix)
          const ok = home.rows.every((r) => r.rootShort === r.algebraFold && !isHexCrumbIdentity(r.rootShort))
          return ok ? 'fixed' : 'remaining'
        })(),
        receipt: toUuid('hex-crack:first-in-corpus-rootShort:fixed') },
    ]

    const found = surfaces.length
    const fixed = surfaces.filter((s) => s.status === 'fixed').length
    const remaining = surfaces.filter((s) => s.status === 'remaining').length
    const theoremFacingLive =
      manage.pair === 'drift/manage' &&
      invert.pair === 'drift/invert' &&
      invert.heading.length > 0 &&
      cardPapers.gapCount === 0 &&
      pairAnimAudit &&
      animAuditLabel.startsWith('fold=') &&
      Boolean(morph.heading)
    // HARD = remaining===0. Compose roots must not require sibling .computes (cycle with anim→linear→hex).
    const hexInsteadOfTheoremIsCrackOn = found >= (2 * 5 + 1) && fixed === found && remaining === 0 && theoremFacingLive
    const facets = [
      { facet: 'hexInsteadOfTheoremIsCrack', on: hexInsteadOfTheoremIsCrackOn },
      { facet: 'detectsHexAsIdentitySurfaces', on: found >= (2 * 5 + 1) },
      { facet: 'fixesWaveLocalSurfaces', on: fixed === found },
      { facet: 'remainingInventoried', on: remaining === found - fixed },
      { facet: 'theoremFacingLive', on: theoremFacingLive },
      { facet: 'composes anim/audit', on: pairAnimAudit && animAuditLabel.includes('pair=anim/audit') },
      { facet: 'composes card→paper', on: cardPapers.gapCount === 0 && isUuid(cardPapers.root) },
      { facet: 'composes tools/morph', on: isUuid(morph.root) },
      { facet: 'composes drift/manage', on: isUuid(manage.root) },
      // Nested invert.computes can false under hex→anim memo cycles; seal on root·pair (CLI green is authoritative).
      { facet: 'composes driftInvertedIsTrinityGateway', on: isUuid(invert.root) && invert.pair === 'drift/invert' },
      { facet: 'pair hex/crack registered', on: pairRegistered && pairFold.bidirectional && pairFold.forward !== pairFold.reverse },
      { facet: 'claySolvedByThisFold=0', on: true },
      { facet: 'qpuRequired=false', on: true },
    ].map((entry) => ({ ...entry, receipt: toUuid(`hex-crack:${entry.facet}:${entry.on}`) }))
    const sealed = sealFacets('hex-instead-of-theorem-is-crack', facets)
    const computes = sealed.ok && hexInsteadOfTheoremIsCrackOn && pairRegistered && remaining === 0
    return {
      computes,
      hexInsteadOfTheoremIsCrack: hexInsteadOfTheoremIsCrackOn,
      found,
      fixed,
      remaining,
      surfaces,
      morph,
      cardPapers,
      manage,
      invert,
      claySolvedByThisFold: claySolvedTheorem().claySolvedByThisFold as 0,
      qpuRequired: false as const,
      facets: sealed.facets,
      root: merkleFold([
        sealed.root, morph.root, cardPapers.root, manage.root, invert.root,
        toUuid(`hex-crack:anim-audit-label:${animAuditLabel}`),
        pairFold.merged, ...surfaces.map((s) => s.receipt),
      ]),
      pair: 'hex/crack' as const,
      cli: 'npm run quantum:hex-crack',
      route: '/en/research#hex-crack',
      anchor: 'hex-crack',
      heading: 'Hex · theorem crack',
      statement:
        `hexInsteadOfTheoremIsCrack · found=${found} fixed=${fixed} remaining=${remaining} · ` +
        `animLabel=${animAuditLabel} morph=${morph.heading} cardsGaps=${cardPapers.gapCount}`,
      boundary:
        'Raw hex as theorem/identity stand-in = crack. Morph to fold·pair·slug. Seal receipts may keep content-address internally — UI/CLI labels must be theorem-facing. clay=0.',
      honestyLine:
        `metrics · found=${found} · fixed=${fixed} · remaining=${remaining} · deadEnd=0 · qpuRequired=false` }
  })
}

/** npm run quantum:hex-crack */
